dot(p2, " $5$ ", (2,4), N);
dot(p2, " $6$ ", (2,2), E);
dot(p2, " $1$ ", (0.5,2), N);
dot(p2, " $2$ ", (-1,2), S);
arr(p2, (-1, 2), (-3, 2)); 
arr(p2, (-3, 2), (-1, 2)); 
arr(p2, (-1, 4), (-1, 2)); 
arr(p2, (2, 4), (2, 2)); 

label(p2, " $\in C_2$ ", (-2,1));
label(p2, " $\in C_1$ ", (.5,1));
label(p2, " $\in C_1$ ", (2,1));

label(" $\longleftrightarrow$ ", (3, 2));

add(shift((8, 0))*p2);
